def flatten(d: dict) -> dict:
    result = {}
    for key, value in d.items():
        if isinstance(value, dict):
            for nested_key, nested_value in value.items():
                result[f"{key}.{nested_key}"] = nested_value
        else:
            result[key] = value
    return result
