import re

def parse_money(s: str) -> float | None:
    if not s or s.lower() in ("", "n/a"):
        return None
    # Remove $, commas, and any other non-digit characters except decimal point
    cleaned = re.sub(r'[^\d.]', '', s)
    try:
        return float(cleaned)
    except ValueError:
        return None
